setcpm(56/4)
song("intro@4 theme@8 turn@4 develop@8 pedal@4 theme'@8 coda@6", "once")
tempomap("0:14 36:14 42:9")

// Adagio sostenuto in cut time: one cycle is one bar. The song line names the sections every track shares: the figure
// alone, the melody over C# minor, a turn to E major, a development through F# minor to the Neapolitan D, a long G# pedal,
// the opening again with the melody doubled an octave below, and a coda that slows into the last chord
const felt = (x) => x.s("triangle").timbre("soft").attack(.005).decay(1.4).sustain(.15).release(1.6).lpf(2200).room(.55).size(.8)

// The triplet figure: four groups of three in every bar
const figIntro = note("<[g#3 c#4 e4]*4 [g#3 c#4 e4]*4 [[a3 c#4 e4]*2 [a3 d4 f#4]*2] [[g#3 c4 f#4] [g#3 c#4 e4] [g#3 c4 d#4] [g#3 c4 d#4]]>")
const figTheme = note("<[g#3 c#4 e4]*4 [g#3 c#4 e4]*4 [g#3 c#4 e4]*4 [a3 c#4 e4]*4 [a3 c#4 f#4]*4 [g#3 c4 d#4]*4 [g#3 c#4 e4]*4 [g#3 c4 d#4]*4>")
const figTurn = note("<[g#3 b3 e4]*4 [a3 b3 d#4]*4 [g#3 b3 e4]*4 [g#3 c4 d#4]*4>")
const figDevelop = note("<[a3 c#4 f#4]*4 [a3 c#4 f#4]*4 [a3 b3 d#4]*4 [g#3 b3 e4]*4 [a3 c#4 e4]*4 [a3 c#4 f#4]*4 [a3 d4 f#4]*4 [g#3 c4 d#4]*4>")
const figPedal = note("<[g#3 c4 d#4]*4 [g#3 c#4 e4]*4 [g#3 c4 f#4]*4 [[g#3 c4 d#4] [c4 d#4 f#4] [d#4 f#4 g#4] [f#4 g#4 c5]]>")
const figCoda = note("<[g#3 c#4 e4]*4 [g#3 c4 d#4]*4 [g#3 c#4 e4]*4 [[g#3 c#4 e4] [c#4 e4 g#4] [e4 g#4 c#5] [g#4 c#5 e5]] [g#3,c#4,e4] [g#3,c#4,e4]>")
triplets: stack(figIntro.sections("intro"), figTheme.sections("theme"), figTurn.sections("turn"), figDevelop.sections("develop"), figPedal.sections("pedal"), figCoda.sections("coda"))
  .felt().gain(bysec("pedal:.26 coda:.17 *:.2"))

// Octaves in the bass, held for the whole bar
const lowIntro = note("<[c#2,c#3] [b1,b2] [[a1,a2] [f#1,f#2]] [g#1,g#2]>")
const lowTheme = note("<[c#2,c#3] [c#2,c#3] [b1,b2] [a1,a2] [f#1,f#2] [g#1,g#2] [c#2,c#3] [g#1,g#2]>")
const lowTurn = note("<[e2,e3] [b1,b2] [e2,e3] [g#1,g#2]>")
const lowDevelop = note("<[f#1,f#2] [e2,e3] [d#2,d#3] [e2,e3] [a1,a2] [f#1,f#2] [d2,d3] [g#1,g#2]>")
const lowPedal = note("[g#1,g#2]")
const lowCoda = note("<[c#2,c#3] [g#1,g#2] [c#2,c#3] [c#2,c#3] [c#1,c#2] [c#1,c#2]>")
bass: stack(lowIntro.sections("intro"), lowTheme.sections("theme"), lowTurn.sections("turn"), lowDevelop.sections("develop"), lowPedal.sections("pedal"), lowCoda.sections("coda"))
  .felt().gain(.34)

// The melody enters with its dotted, repeated G#, rises in the turn and the development, waits through the pedal and
// settles on C# in the coda. On the return (theme') it is doubled an octave below
const tuneTheme = note("<[~@12 g#4@3 g#4] [g#4@8 ~@4 g#4@3 g#4] [g#4@8 ~@4 g#4@3 g#4] [a4@8 ~@4 a4@3 a4] [a4@8 ~@4 f#4@3 f#4] [g#4@8 ~@4 g#4@3 g#4] [e4@8 ~@4 g#4@3 g#4] [g#4@12 g#4@3 g#4]>")
const tuneTurn = note("<[g#4@3 b4 e5@4] [f#5@4 d#5@4] [e5@3 b4 g#4@4] [g#4@8]>")
const tuneDevelop = note("<[c#5@8 ~@4 c#5@3 c#5] [c#5@8 b4@8] [b4@8 ~@4 a4@3 a4] [g#4@16] [a4@8 ~@4 c#5@3 c#5] [c#5@8 a4@8] [d5@8 ~@4 d5@3 d5] [c5@16]>")
const tuneCoda = note("<[g#4@8 ~@4 g#4@3 g#4] [g#4@8 f#4@4 d#4@4] [e4@8 c#4@8] ~ ~ ~>")
melody: stack(tuneTheme.sections("theme"), tuneTurn.sections("turn"), tuneDevelop.sections("develop"), tuneCoda.sections("coda"))
  .variant(x => x.superimpose(y => y.add(-12)))
  .s("sine").fm(.8).fmh(2).attack(.01).decay(1.8).sustain(.2).release(2).room(.6).gain(.3)

setcpm(50)
song("(theme@7 1.again@1 2.onward@1)*2 (episode@8 theme@7 1.onward@1 2.home@1)*2 storm@8 storm'@8 descent@4 theme@7 last@2", "once")
tempomap("0:50 72:50 77:32")

// 3/8: one cycle is a bar of six sixteenths. The repeats and endings are written in the song line, as in the score:
// the theme twice, then episode and theme twice, the stormy section over an A pedal, the fall back and the theme to close
const keys = (x) => x.s("triangle").timbre("soft").attack(.003).decay(.5).sustain(.05).release(.5).lpf(3200).room(.4)

// The theme's seven bars; its eighth bar is an ending: the pickup back (again), the climb into the episode (onward)
// or a plain A (home)
const theme = note("<[e5 d#5 e5 b4 d5 c5] [a4@2 ~ c4 e4 a4] [b4@2 ~ e4 g#4 b4] [c5@2 ~ e4 e5 d#5] [e5 d#5 e5 b4 d5 c5] [a4@2 ~ c4 e4 a4] [b4@2 ~ e4 c5 b4]>")
const again = note("[a4@4 e5 d#5]")
const onward = note("[a4@2 ~ b4 c5 d5]")
const home = note("[a4@6]")
// The episode steps down through C, G and A minor, then the E and D# trill lead back
const episode = note("<[e5@3 g4 f5 e5] [d5@3 f4 e5 d5] [c5@3 e4 d5 c5] [b4@2 ~ e4 e5 ~] [~ e5 e6 ~ ~ d#5] [e5 ~ ~ d#5 e5 d#5] [e5 d#5 e5 d#5 e5 d#5] [e5@2 ~@2 e5 d#5]>")
// The storm: D minor and B-flat chords over the A pedal, ending on E
const storm = note("<[[d5,f5]@3 [c#5,e5] [d5,f5] [e5,g5]] [[f5,a5]@6] [[d5,f5]@3 [c#5,e5] [d5,f5] [e5,g5]] [[f5,a5]@3 [e5,g5] [d5,f5] [c#5,e5]] [[bb4,d5,f5]@3 [bb4,d5,f5] [bb4,d5,g5] [bb4,d5,f5]] [[bb4,d5,f5]@6] [[a4,c#5,e5]@3 [a4,c#5,g5] [a4,c#5,f5] [a4,c#5,e5]] [[a4,d5,f5]@3 [g#4,b4,e5]@3]>")
// A diminished arpeggio up, a chromatic fall and the trill into the theme
const descent = note("<[g#4 b4 d5 f5 g#5 b5] [e6 d#6 d6 c#6 c6 b5] [bb5 a5 g#5 g5 f#5 f5] [e5 d#5 e5 d#5 e5 d#5]>")
const last = note("<[a4@6] ~>")
// The second storm (storm') is doubled an octave higher
theme_r: stack(theme.sections("theme"), again.sections("again"), onward.sections("onward"), home.sections("home"), episode.sections("episode"), storm.sections("storm"), descent.sections("descent"), last.sections("last"))
  .variant(x => x.superimpose(y => y.add(12)))
  .keys().gain(bysec("storm:.32 storm':.34 descent:.3 *:.27"))

// The left hand: rising arpeggios on A minor and E, broken chords under the episode, the hammered A under the storm
const leftTheme = note("<~ [~@2 a2 e3 a3 ~] [~@2 e2 e3 g#3 ~] [~@2 a2 e3 a3 ~] ~ [~@2 a2 e3 a3 ~] [~@2 e2 e3 g#3 ~]>")
const leftCadence = note("[~@2 a2 e3 a3 ~]")
const leftEpisode = note("<[c3 g3 c4 ~@3] [g2 g3 b3 ~@3] [a2 e3 a3 ~@3] [e2 e3 e4 ~@3] ~ ~ ~ ~>")
const leftStorm = note("a2*6")
const leftDescent = note("<[e2,e3] ~ ~ ~>")
const leftLast = note("<[a2,e3,a3] ~>")
left: stack(leftTheme.sections("theme"), leftCadence.sections("again onward home"), leftEpisode.sections("episode"), leftStorm.sections("storm"), leftDescent.sections("descent"), leftLast.sections("last"))
  .keys().gain(bysec("storm:.26 storm':.28 *:.22"))

setcpm(60/3)
song("intro@4 first@8 answer@8 rise@8 first@8 interlude@4 first'@8 answer'@8 rise'@8 close@8", "once")
tempomap("0:20 64:20 72:14")

// One cycle is a bar of 3/4. Lent et douloureux. Two halves: the accompaniment alone, the first phrase, its answer,
// a higher phrase over new chords, the first phrase again; a pause; then the same once more, doubled, and a close on D.
// Every section is an even number of bars, so the melody stays in step with the two-bar accompaniment
const felt = (x) => x.s("triangle").timbre("soft").attack(.01).decay(2.5).sustain(.1).release(2).lpf(1800).room(.6).size(.85)

// The accompaniment: a low note on the first beat, a chord on the second. Gmaj7 and Dmaj7 everywhere except under the
// higher phrase, which moves through Bm, A, D and G, and the close, which settles on D
const sway = note("<[g2 [b3,d4,f#4]@2] [d2 [a3,c#4,f#4]@2]>")
const turn = note("<[b1 [a3,d4,f#4]@2] [a1 [g3,c#4,e4]@2] [d2 [a3,d4,f#4]@2] [g2 [b3,d4,f#4]@2] [a1 [g3,c#4,e4]@2] [d2 [a3,d4,f#4]@2] [g2 [b3,d4,f#4]@2] [d2 [a3,c#4,f#4]@2]>")
const settle = note("<[g2 [b3,d4,f#4]@2] [d2 [a3,c#4,f#4]@2] [g2 [b3,d4,f#4]@2] [d2 [a3,c#4,f#4]@2] [e2 [g3,b3,d4]@2] [d2 [a3,d4,f#4]@2] [d2,a2,d3,f#3] ~>")
left: stack(sway.exceptSections("rise close"), turn.sections("rise"), settle.sections("close"))
  .felt().gain(.3)

const phrase1 = note("<[f#5@2 a5] [g5@2 f#5] [c#5@2 b4] [c#5@2 d5] a4 ~ f#4 ~>")
const phrase2 = note("<[f#5@2 a5] [g5@2 f#5] [c#5@2 b4] [c#5@2 d5] a4 ~ [c#5@2 d5] e5>")
const phrase3 = note("<[f#5@2 g5] [a5@2 e5] [d5@2 c#5] [b4@2 a4] [b4@2 c#5] d5 ~ ~>")
const ending = note("<[f#5@2 a5] [g5@2 f#5] [c#5@2 b4] [c#5@2 d5] [f#4@2 e4] d4 ~ ~>")

// The second time through (the primed sections) the melody is doubled an octave below
melody: stack(phrase1.sections("first"), phrase2.sections("answer"), phrase3.sections("rise"), ending.sections("close"))
  .variant(x => x.superimpose(y => y.add(-12)))
  .s("sine").fm(.5).fmh(2).attack(.02).decay(2).sustain(.2).release(2).room(.6).gain(.26)

setcpm(20)
song("opening@8 second@8 flow@8 flow'@8 climax@4 opening'@8 coda@6", "once")
// Slow at first, un poco mosso for the flowing middle, easing back for the return and slowing to the end
tempomap("0:20 16:20 16:26 34:26 36:22 36:20 46:20 50:13")

// 9/8: one cycle is a bar of three groups of three eighths. An impression in the spirit of the piece, not a transcription
const felt = (x) => x.s("triangle").timbre("soft").attack(.008).decay(2).sustain(.15).release(2).lpf(2000).room(.65).size(.85)

// Rolling arpeggios. Opening: Db, Gb, Ab7, Db, Bbm, Gb, Ab7, Db. Second: Ebm, Ab7, Db, Bbm, Gbmaj7, Ebm, Ab7, Db.
// Flow: nine eighths through two octaves on Db, Bbm, Gb, Ab7, Db, Fm, Gb, Ab7. Climax: Gb, Ab7, Bbm, Ab7
const arpA = note("<[db3 ab3 f4]*3 [gb2 db3 bb3]*3 [ab2 eb3 c4]*3 [db3 ab3 f4]*3 [bb2 f3 db4]*3 [gb2 db3 bb3]*3 [ab2 eb3 c4]*3 [db3 ab3 f4]*3>")
const arpB = note("<[eb3 gb3 db4]*3 [ab2 eb3 gb3]*3 [db3 f3 ab3]*3 [bb2 db3 f3]*3 [gb2 bb2 f3]*3 [eb3 gb3 bb3]*3 [ab2 c3 gb3]*3 [db3 ab3 f4]*3>")
const arpFlow = note("<[db3 ab3 db4 f4 ab4 db5 ab4 f4 db4] [bb2 f3 bb3 db4 f4 bb4 f4 db4 bb3] [gb2 db3 gb3 bb3 db4 gb4 db4 bb3 gb3] [ab2 eb3 ab3 c4 gb4 ab4 gb4 c4 ab3] [db3 ab3 db4 f4 ab4 db5 ab4 f4 db4] [f2 c3 f3 ab3 c4 f4 c4 ab3 f3] [gb2 db3 gb3 bb3 db4 gb4 db4 bb3 gb3] [ab2 eb3 ab3 c4 gb4 ab4 gb4 c4 ab3]>")
const arpClimax = note("<[gb2 db3 bb3]*3 [ab2 eb3 c4]*3 [bb2 f3 db4]*3 [ab2 eb3 gb3]*3>")
const arpCoda = note("<[db3 ab3 f4]*3 [gb2 db3 bb3]*3 [db3 ab3 f4]*3 [gb2 db3 bb3]*3 [db3 ab3 f4]*3 [db3,ab3,db4,f4]>")
// The filter opens and closes through every section
arp: stack(arpA.sections("opening"), arpB.sections("second"), arpFlow.sections("flow"), arpClimax.sections("climax"), arpCoda.sections("coda"))
  .felt().lpf(env("1400 2600 1400", "section")).gain(bysec("flow:.2 flow':.2 climax:.24 coda:.15 *:.17"))

// The roots, held
const rootsA = note("<db2 gb1 ab1 db2 bb1 gb1 ab1 db2>")
const rootsB = note("<eb2 ab1 db2 bb1 gb1 eb2 ab1 db2>")
const rootsFlow = note("<db2 bb1 gb1 ab1 db2 f1 gb1 ab1>")
const rootsClimax = note("<gb1 ab1 bb1 ab1>")
const rootsCoda = note("<db2 gb1 db2 gb1 db2 db2>")
bass: stack(rootsA.sections("opening"), rootsB.sections("second"), rootsFlow.sections("flow"), rootsClimax.sections("climax"), rootsCoda.sections("coda"))
  .felt().gain(.3)

// The melody floats above, three beats to a note in the outer sections and in long notes over the flowing middle.
// The second flow and the return are doubled an octave below
const lineA = note("<[ab4@3 db5@3 f5@3] [gb5@3 f5@3 db5@3] [eb5@3 db5@3 c5@3] [db5@6 ~@3] [f5@3 db5@3 bb4@3] [bb4@3 db5@3 gb5@3] [ab5@3 f5@3 eb5@3] [db5@9]>")
const lineB = note("<[bb4@3 db5@3 eb5@3] [gb5@3 f5@3 eb5@3] [f5@6 ab4@3] [db5@3 f5@3 bb5@3] [bb5@3 ab5@3 f5@3] [gb5@3 eb5@3 db5@3] [c5@3 eb5@3 gb5@3] [f5@9]>")
const lineFlow = note("<[f5@6 eb5@3] [db5@6 f5@3] [bb5@6 ab5@3] [gb5@6 eb5@3] [f5@6 ab5@3] [ab5@6 f5@3] [bb5@6 gb5@3] [ab5@3 gb5@3 eb5@3]>")
const lineClimax = note("<[bb5@6 db6@3] [c6@6 ab5@3] [db6@6 bb5@3] [ab5@9]>")
const lineCoda = note("<[f5@3 eb5@3 db5@3] [db5@3 bb4@3 ab4@3] [ab4@6 ~@3] [bb4@3 db5@3 bb4@3] [ab4@9] [f4@9]>")
melody: stack(lineA.sections("opening"), lineB.sections("second"), lineFlow.sections("flow"), lineClimax.sections("climax"), lineCoda.sections("coda"))
  .variant(x => x.superimpose(y => y.add(-12)))
  .s("sine").fm(.7).fmh(2).attack(.03).decay(2).sustain(.25).release(2.2).room(.7).gain(.26)

setcpm(72/4)
song("opening@11 wander@8 descent@4 pedal@8 close@4", "once")
tempomap("0:18 31:18 35:11")

// One cycle is a bar of sixteen sixteenths: the pattern x1 x2 x3 x4 x5 x3 x4 x5, played twice. All thirty-five bars,
// in five sections: the opening, the wandering middle, the descent, the dominant pedal and the close over C
const felt = (x) => x.s("triangle").timbre("soft").attack(.003).decay(1.1).sustain(.1).release(1.2).lpf(2600).room(.4)

// Opening: C, Dm7/C, G7/B, C, Am/C, D7/C, G/B, Cmaj7/B, Am7, D7, G
const barsOpening = note("<[c4 e4 g4 c5 e5 g4 c5 e5]*2 [c4 d4 a4 d5 f5 a4 d5 f5]*2 [b3 d4 g4 d5 f5 g4 d5 f5]*2 [c4 e4 g4 c5 e5 g4 c5 e5]*2 [c4 e4 a4 e5 a5 a4 e5 a5]*2 [c4 d4 f#4 a4 d5 f#4 a4 d5]*2 [b3 d4 g4 d5 g5 g4 d5 g5]*2 [b3 c4 e4 g4 c5 e4 g4 c5]*2 [a3 c4 e4 g4 c5 e4 g4 c5]*2 [d3 a3 d4 f#4 c5 d4 f#4 c5]*2 [g3 b3 d4 g4 b4 d4 g4 b4]*2>")
// Wander: C#dim7/G, Dm/F, Fdim7, C/E, Fmaj7/E, Dm7, G7, C
const barsWander = note("<[g3 bb3 e4 g4 c#5 e4 g4 c#5]*2 [f3 a3 d4 a4 d5 d4 a4 d5]*2 [f3 ab3 d4 f4 b4 d4 f4 b4]*2 [e3 g3 c4 g4 c5 c4 g4 c5]*2 [e3 f3 a3 c4 f4 a3 c4 f4]*2 [d3 f3 a3 c4 f4 a3 c4 f4]*2 [g2 d3 g3 b3 f4 g3 b3 f4]*2 [c3 e3 g3 c4 e4 g3 c4 e4]*2>")
// Descent: C7, Fmaj7, F#dim7, Abdim7
const barsDescent = note("<[c3 g3 bb3 c4 e4 bb3 c4 e4]*2 [f2 f3 a3 c4 e4 a3 c4 e4]*2 [f#2 c3 a3 c4 eb4 a3 c4 eb4]*2 [ab2 f3 b3 c4 d4 b3 c4 d4]*2>")
// Over the G pedal: G7, C/G, G7sus4, G7, dim7/G, C/G, G7sus4, G7
const barsPedal = note("<[g2 f3 g3 b3 d4 g3 b3 d4]*2 [g2 e3 g3 c4 e4 g3 c4 e4]*2 [g2 d3 g3 c4 f4 g3 c4 f4]*2 [g2 d3 g3 b3 f4 g3 b3 f4]*2 [g2 eb3 a3 c4 f#4 a3 c4 f#4]*2 [g2 e3 g3 c4 g4 g3 c4 g4]*2 [g2 d3 g3 c4 f4 g3 c4 f4]*2 [g2 d3 g3 b3 f4 g3 b3 f4]*2>")
// Over the C pedal: C7, the figure turned down through F, up through G7, and the final chord
const barsClose = note("<[c2 c3 g3 bb3 e4 g3 bb3 e4]*2 [c2 c3 f3 a3 c4 f4 c4 a3 c4 a3 f3 a3 f3 d3 f3 d3] [c2 b2 g4 b4 d5 f5 d5 b4 d5 b4 g4 b4 d4 f4 e4 d4] [c2,c3,e4,g4,c5]>")
prelude: stack(barsOpening.sections("opening"), barsWander.sections("wander"), barsDescent.sections("descent"), barsPedal.sections("pedal"), barsClose.sections("close"))
  .felt().gain(bysec("pedal:.25 close:.24 *:.22"))

// A bass an octave below the lowest note of each bar, held
const rootsOpening = note("<c3 c3 b2 c3 c3 c3 b2 b2 a2 d2 g2>")
const rootsWander = note("<g2 f2 f2 e2 e2 d2 g1 c2>")
const rootsDescent = note("<c2 f1 f#1 ab1>")
bass: stack(rootsOpening.sections("opening"), rootsWander.sections("wander"), rootsDescent.sections("descent"), note("g1").sections("pedal"), note("c1").sections("close"))
  .felt().gain(.28)

setcpm(60/2)
song("ground@8 theme@16 pairs@16 runs@16 leaps@16 theme'@16 close@8 end@8", "once")
tempomap("0:30 100:30 104:20")

// One cycle is one chord; the ground (D, A, Bm, F#m, G, D, G, A) takes eight. The second violin plays the first violin's
// line one ground later, so every section is a whole number of grounds. The close turns the ground into a cadence
const bowed = (x, bright = 2800) => x.s("sawtooth").vib(5.5).vibdepth(.1).attack(.05).sustain(.7).release(.3).lpf(bright)

// The theme: one note per chord
const theme = note("<f#5 e5 d5 c#5 b4 a4 b4 c#5>")
// First variation: two notes to a chord
const pairs = note("<[d5 f#5] [c#5 e5] [b4 d5] [a4 c#5] [b4 d5] [a4 f#4] [g4 b4] [a4 c#5]>")
// Second variation: the falling line, four notes to a chord
const runs = note("<[d5 f#5 a5 g5] [f#5 d5 f#5 e5] [d5 b4 d5 a4] [g4 b4 a4 g4] [f#4 d4 g4 f#4] [e4 g4 f#4 e4] [d4 b3 b4 c#5] [d5 c#5 b4 a4]>")
// Third variation: each chord leaps down an octave and climbs back
const leaps = note("<[f#5 f#4 a4 d5] [e5 e4 a4 c#5] [d5 d4 f#4 b4] [c#5 c#4 f#4 a4] [b4 b3 d4 g4] [a4 a3 d4 f#4] [b4 b3 d4 g4] [c#5 c#4 e4 a4]>")
// The cadence: the theme coming home to D
const cadence = note("<f#5 e5 d5 c#5 b4 a4 [b4 c#5] d5>")

// The line every violin follows. When the theme returns (theme') it is played in octaves
const line = stack(theme.sections("theme"), pairs.sections("pairs"), runs.sections("runs"), leaps.sections("leaps"), cadence.sections("close"))
  .variant(x => x.superimpose(y => y.add(12)))

// The ground, ending D, A, Bm, F#m, G, D, A, D in the close
const ground = note("<d3 a2 b2 f#2 g2 d2 g2 a2>")
const groundHome = note("<d3 a2 b2 f#2 g2 d2 a2 d2>")
cello: stack(ground.exceptSections("close end"), groundHome.sections("close end"))
  .s("sawtooth").lpf(700).attack(.04).sustain(.7).release(.4).room(.4).gain(.3)

// A plucked arpeggio of each chord, from the theme until the close
pluck: note("<[d4 f#4 a4 d5] [a3 c#4 e4 a4] [b3 d4 f#4 b4] [a3 c#4 f#4 a4] [b3 d4 g4 b4] [a3 d4 f#4 a4] [b3 d4 g4 b4] [a3 c#4 e4 a4]>").exceptSections("ground close end")
  .s("square").pw(.15).attack(.002).decay(.3).sustain(0).release(.2).lpf(3200).room(.4).gain(bysec("leaps:.12 *:.1"))

// The canon: the second violin one full ground behind the first. The viola doubles the first violin an octave down
// from the first variation on
violin1: line.bowed(3200).pan(.3).room(.5).gain(.18)
violin2: line.late(8).bowed().pan(.7).room(.5).gain(.17)
viola: stack(pairs.sections("pairs"), runs.sections("runs"), leaps.sections("leaps"), theme.sections("theme'"), cadence.sections("close")).add(-12)
  .bowed(1800).room(.5).gain(.16)

