// The figure: the A against the falling line, the same on B-flat, then down from A, down from F, up through A7,
// up through D minor and onto the diminished chord
const figure = note("<[a4 g4 a4 f4 a4 e4 a4 d4 a4 c#4 a4 d4 a4 e4 a4 f4] [a4 g4 a4 f4 a4 e4 a4 d4 a4 c#4 a4 d4 a4 e4 a4 f4] [bb4 a4 bb4 g4 bb4 f4 bb4 e4 bb4 d4 bb4 e4 bb4 f4 bb4 g4] [a4 g4 f4 e4 d4 c#4 d4 e4]*2 [f4 e4 d4 c#4 bb3 a3 bb3 c#4]*2 [a3 c#4 e4 g4 bb4 g4 e4 c#4]*2 [d4 f4 a4 d5 f5 a5 d6 a5]*2 [c#5,e5,g5,bb5]>")
// A run up through D minor and back down to the low D
const cadenza = note("<[d5 e5 f5 g5 a5 bb5 c#6 d6 e6 f6 e6 d6 c#6 bb5 a5 g5] [f5 e5 d5 c#5 bb4 a4 g4 f4 e4 d4 c#4 d4 e4 f4 g4 e4] [d4@8 ~@8] ~>")
